package main

import (
    "fmt"
    "slices"
)

func main() {
    var left any = []int{1, 2}
    var right any = []int{1, 2}

    fmt.Printf("types: %T and %T\n", left, right)
    a, okA := left.([]int)
    b, okB := right.([]int)
    fmt.Println("same contents:", okA && okB && slices.Equal(a, b))
}

